// Seed the inventory by searching for Gemini-specific usage. Each hit becomes an owned row.
const markers: Record<string, { pattern: RegExp; why: string }> = {
  legacySdk: { pattern: /@google\/generative-?ai/, why: "legacy library, deprecated since 2025-11-30; move to @google/genai" },
  generateContent: { pattern: /models\.generateContent|generateContentStream/, why: "supported but legacy; Interactions API recommended" },
  interactionsOutputs: { pattern: /interaction\.outputs/, why: "May 2026 Interactions change: outputs became steps" },
  responseMimeType: { pattern: /response_mime_type|responseMimeType/, why: "Interactions uses response_format" },
  thinkingBudget: { pattern: /thinking_budget|thinkingBudget/, why: "newer models use thinking_level" },
  samplingParams: { pattern: /temperature|top_p|topP|top_k|topK/, why: "removed for the newest Flash model per current guidance" },
  candidateCount: { pattern: /candidate_count|candidateCount/, why: "unsupported in Gemini 3 and later" },
  safetySettings: { pattern: /safetySettings/, why: "not yet available in the Interactions API" },
  modelLiteral: { pattern: /model:\s*["'`]gemini-/, why: "model ids belong in configuration" },
};

interface GeminiDependency {
  id: string;
  marker: keyof typeof markers | "manual";
  location: string;
  owner: string;
  risk: "low" | "medium" | "high";
  verification: string;
}

