import { GoogleGenAI } from "@google/genai";

// Portable contract in the application's own terms.
interface FeedbackResult {
  text: string | null;
  outcome: "ok" | "blocked" | "incomplete" | "failed";
  providerDetail: string; // native reason kept for evidence, never silently dropped
  totalTokens?: number;
}

interface FeedbackProvider {
  draftFeedback(report: string): Promise<FeedbackResult>;
}

// Gemini-specific adapter: Interactions status, steps, and usage stay behind this boundary.
class GeminiFeedback implements FeedbackProvider {
  constructor(private ai: GoogleGenAI, private model: string, private systemInstruction: string) {}

  async draftFeedback(report: string): Promise<FeedbackResult> {
    const interaction = await this.ai.interactions.create({
      model: this.model,
      system_instruction: this.systemInstruction,
      input: report,
      store: false,
    });
    const totalTokens = interaction.usage?.total_tokens;
    switch (interaction.status) {
      case "completed":
        return { text: interaction.output_text ?? null, outcome: "ok", providerDetail: "completed", totalTokens };
      case "incomplete":
        return { text: null, outcome: "incomplete", providerDetail: "incomplete", totalTokens };
      default:
        return { text: null, outcome: "failed", providerDetail: interaction.status, totalTokens };
    }
  }
}

