// Baseline (generateContent) and candidate (Interactions) report outcomes differently.
// Normalize both before comparing, so "blocked" and "incomplete" are counted the same way.
type Normalized = "ok" | "blocked" | "incomplete" | "failed";

function fromFinishReason(reason: string | undefined, promptBlocked: boolean): Normalized {
  if (promptBlocked) return "blocked";
  if (reason === "STOP") return "ok";
  if (reason === "MAX_TOKENS") return "incomplete";
  if (reason === "SAFETY" || reason === "PROHIBITED_CONTENT" || reason === "SPII" || reason === "BLOCKLIST") return "blocked";
  return "failed";
}

function fromInteractionStatus(status: string): Normalized {
  if (status === "completed") return "ok";
  if (status === "incomplete") return "incomplete";
  return "failed";
}

interface ShadowComparison {
  caseId: string;
  slice: string;
  modality: string;
  baseline: { outcome: Normalized; rubricScore: number; latencyMs: number; totalTokens: number };
  candidate: { outcome: Normalized; rubricScore: number; latencyMs: number; totalTokens: number };
}

// Thresholds are fixed before traffic moves; any critical slice regression holds the rollout.
function canaryGate(rows: ShadowComparison[], criticalSlices: string[]) {
  const regressed = rows.filter(
    (r) => criticalSlices.includes(r.slice) && (r.candidate.rubricScore < r.baseline.rubricScore || r.candidate.outcome !== r.baseline.outcome),
  );
  const newBlocks = rows.filter((r) => r.candidate.outcome === "blocked" && r.baseline.outcome === "ok");
  if (regressed.length) return { decision: "rollback", cases: regressed.map((r) => r.caseId) };
  if (newBlocks.length) return { decision: "hold", reason: "new safety blocks need review", cases: newBlocks.map((r) => r.caseId) };
  return { decision: "promote" };
}

